import assert from "node:assert/strict";
import { test } from "node:test";
import { checkpointMessage } from "../src/checkpoint.js";

test("a step becomes a wip commit message that skips CI", () => {
  assert.equal(checkpointMessage("RH-1234", "Add the empty card"), "wip(RH-1234): Add the empty card [skip ci]");
});

test("only the first line of a step title is used", () => {
  assert.equal(checkpointMessage("RH-1234", "Add the card\nand also rewrite the table"), "wip(RH-1234): Add the card [skip ci]");
});

export interface Broker {
  post(text: string): Promise<void>;
}

export const makeReporter = (broker: Broker) => {
  let last = "";
  return async (step: string) => {
    if (step === last) return;
    last = step;
    await broker.post(`Nova is on: ${step}`);
  };
};

import assert from "node:assert/strict";
import { mock, test } from "node:test";

test("the same step is posted only once", async () => {
  const post = mock.fn(async (_text: string) => {});
  const report = makeReporter({ post });

  await report("plan");
  await report("plan");
  await report("build");

  assert.equal(post.mock.callCount(), 2);
  assert.deepEqual(post.mock.calls[1]?.arguments, ["Nova is on: build"]);
});

import assert from "node:assert/strict";
import { test } from "node:test";
import { CreateTagsCommand, EC2Client } from "@aws-sdk/client-ec2";
import { mockClient } from "aws-sdk-client-mock";
import { tagForRun } from "../src/tags.js";

const ec2Mock = mockClient(EC2Client);

test("tagForRun tags the VM with its run id", async () => {
  ec2Mock.reset();
  ec2Mock.on(CreateTagsCommand).resolves({});

  await tagForRun(new EC2Client({ region: "us-east-1" }), "i-0abc", "run-7f3a2c");

  const calls = ec2Mock.commandCalls(CreateTagsCommand);
  assert.equal(calls.length, 1);
  assert.deepEqual(calls[0]?.args[0].input.Tags, [{ Key: "ai-agents:run-id", Value: "run-7f3a2c" }]);
});

test("an AWS error reaches the caller", async () => {
  ec2Mock.reset();
  ec2Mock.on(CreateTagsCommand).rejects(new Error("UnauthorizedOperation"));

  await assert.rejects(tagForRun(new EC2Client({ region: "us-east-1" }), "i-0abc", "run-7f3a2c"), /UnauthorizedOperation/);
});

