// src/heartbeat.ts
const FIVE_MINUTES = 5 * 60 * 1000;

export const isDead = (lastHeartbeatAt: number, now = Date.now()) => now - lastHeartbeatAt > FIVE_MINUTES;

// test/heartbeat.test.ts
import assert from "node:assert/strict";
import { test } from "node:test";
import { isDead } from "../src/heartbeat.js";

const last = Date.parse("2026-10-16T10:00:00Z");

test("a VM that sent a heartbeat 30 seconds ago is alive", () => {
  assert.equal(isDead(last, last + 30_000), false);
});

test("a VM silent for exactly five minutes is still alive", () => {
  assert.equal(isDead(last, last + 5 * 60_000), false);
});

test("a VM silent for more than five minutes is dead", () => {
  assert.equal(isDead(last, last + 5 * 60_000 + 1), true);
});
